{
 "app_name": "todoist",
 "api_name": "create_task",
 "path": "/projects/{project_id}/tasks",
 "method": "POST",
 "description": "Create a new task within a project.",
 "parameters": [
  {
   "name": "project_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the project. If set to 0, the task will be created in your default/inbox project.",
   "default": null,
   "constraints": []
  },
  {
   "name": "title",
   "type": "string",
   "required": true,
   "description": "The title of the task.",
   "default": null,
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from todoist app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "section_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the section within the project.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "The description of the task.",
   "default": "",
   "constraints": []
  },
  {
   "name": "due_date",
   "type": "string",
   "required": false,
   "description": "The due date of the task in YYYY-MM-DD format.",
   "default": null,
   "constraints": []
  },
  {
   "name": "duration",
   "type": "number",
   "required": false,
   "description": "The duration of the task.",
   "default": null,
   "constraints": []
  },
  {
   "name": "duration_unit",
   "type": "string",
   "required": false,
   "description": "The unit of the task duration.",
   "default": null,
   "constraints": [
    "value in ['minutes', 'hours', 'days']"
   ]
  },
  {
   "name": "order_index",
